     so that a large send() from the protocol layer (e.g. a 1MB DICT URL)
     cannot stall indefinitely when the kernel socket buffer fills up. */
  flags = fcntl(fds[0], F_GETFL, 0);
  status = fcntl(fds[0], F_SETFL, flags | O_NONBLOCK);

